mapper.select:
select id, category_id AS categoryId, name, price, status, description, image, create_time AS createTime, update_time AS updateTime, create_user AS createUser, update_user AS updateUser from setmeal
and name like concat('%',#{name},'%')
and category_id = #{categoryId}
and status = #{status}

select id, category_id AS categoryId, name, price, status, description, image, create_time AS createTime, update_time AS updateTime, create_user AS createUser, update_user AS updateUser from setmeal
and status = #{status}
order by update_time desc

select * from setmeal
where status = 1
and category_id = #{type}
